-- Esboço mínimo do banco de produção (tabelas e funções auxiliares, sem dados) para testar migrações num Postgres local.
-- auth.uid() lê a configuração test.uid. Ver supabase/tests/README.md.
do $$ begin create role anon; exception when duplicate_object then null; end $$;
do $$ begin create role authenticated; exception when duplicate_object then null; end $$;
do $$ begin create role service_role; exception when duplicate_object then null; end $$;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.uid', true), '')::uuid $$;
grant usage on schema auth to public;
create table public.boxes (id bigint generated by default as identity, user_id uuid not null, source text not null, run_id bigint, created_at timestamp with time zone default now() not null, opened_at timestamp with time zone, prize_kind text, prize_amount integer, prize_item text, PRIMARY KEY (id));
create table public.profiles (id uuid not null, name text, name_changes integer default 0 not null, name_changed_at timestamp with time zone, created_at timestamp with time zone default now() not null, last_seen timestamp with time zone default now() not null, show_photo boolean default true not null, UNIQUE (name), PRIMARY KEY (id));
create table public.items_owned (user_id uuid not null references public.profiles on delete cascade, item_id text not null, source text not null, created_at timestamp with time zone default now() not null, PRIMARY KEY (user_id, item_id));
create table public.ledger (id bigint generated by default as identity, user_id uuid not null references public.profiles on delete cascade, currency text not null check (currency = any (array['chip','zcoin'])), delta integer not null, reason text not null, ref text, run_id bigint, created_at timestamp with time zone default now() not null, PRIMARY KEY (id));
create table public.map_stats (user_id uuid not null, map_id text not null, matches integer default 0 not null, wins integer default 0 not null, kills integer default 0 not null, play_seconds bigint default 0 not null, best_wave integer default 0 not null, best_kills integer default 0 not null, best_seconds integer default 0 not null, best_at timestamp with time zone, PRIMARY KEY (user_id, map_id));
create table public.mission_pool (id integer not null, kind text not null, target integer not null, text text not null, coins integer not null, xp integer not null, zcoin integer default 0 not null, chips integer default 0 not null, PRIMARY KEY (id));
create table public.mission_progress (user_id uuid not null, week date not null, slot integer not null, progress integer default 0 not null, claimed boolean default false not null, PRIMARY KEY (user_id, week, slot));
create table public.mission_week (week date not null, slot integer not null, kind text not null, target integer not null, text text not null, coins integer not null, xp integer not null, zcoin integer not null, chips integer not null, PRIMARY KEY (week, slot));
create table public.pass_progress (user_id uuid not null, season integer not null, xp integer default 0 not null, premium boolean default false not null, claimed_free integer[] default '{}'::integer[] not null, claimed_prem integer[] default '{}'::integer[] not null, PRIMARY KEY (user_id, season));
create table public.pass_rewards (season integer not null, level integer not null, track text not null, kind text not null, amount integer default 0 not null, item_id text, PRIMARY KEY (season, level, track));
create table public.player_stats (user_id uuid not null, matches integer default 0 not null, wins integer default 0 not null, kills integer default 0 not null, deaths integer default 0 not null, shots bigint default 0 not null, hits bigint default 0 not null, bosses integer default 0 not null, best_wave integer default 0 not null, play_seconds bigint default 0 not null, updated_at timestamp with time zone default now() not null, PRIMARY KEY (user_id));
create table public.progress (user_id uuid not null, data jsonb default '{}'::jsonb not null, ts bigint default 0 not null, imported_local boolean default false not null, updated_at timestamp with time zone default now() not null, PRIMARY KEY (user_id));
create table public.runs (id bigint generated by default as identity, user_id uuid not null, map_id text not null, started_at timestamp with time zone default now() not null, ended_at timestamp with time zone, wave integer, kills integer, seconds integer, shots integer, hits integer, bosses integer, won boolean, accepted boolean, reason text, PRIMARY KEY (id));
create table public.seasons (id integer not null, name text not null, starts_at timestamp with time zone not null, ends_at timestamp with time zone not null, levels integer default 40 not null, xp_per integer default 1000 not null, premium_price integer default 600 not null, PRIMARY KEY (id));
create table public.shop_items (item_id text not null, rarity integer not null, price_z integer, kind text default 'item'::text not null, active boolean default true not null, PRIMARY KEY (item_id));
create table public.skill_costs (skill text not null, level integer not null, chips integer not null, PRIMARY KEY (skill, level));
create table public.skill_levels (user_id uuid not null, skill text not null, level integer default 0 not null, PRIMARY KEY (user_id, skill));
create table public.wallets (user_id uuid not null references public.profiles on delete cascade, chips integer default 0 not null check (chips >= 0), zcoin integer default 0 not null check (zcoin >= 0), updated_at timestamp with time zone default now() not null, skills_imported boolean default false not null, PRIMARY KEY (user_id));
create table public.xp_events (id bigint generated by default as identity, name text not null, starts_at timestamp with time zone not null, ends_at timestamp with time zone not null, mult numeric(3,1) default 2 not null, PRIMARY KEY (id));
CREATE FUNCTION public.cur_season() RETURNS integer LANGUAGE sql STABLE SET search_path TO '' AS $function$ select id from public.seasons where now() >= starts_at and now() < ends_at order by id desc limit 1; $function$;
CREATE FUNCTION public.cur_week() RETURNS date LANGUAGE sql STABLE SET search_path TO '' AS $function$ select date_trunc('week', now() at time zone 'America/Sao_Paulo')::date; $function$;
CREATE FUNCTION public.ensure_week() RETURNS date LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
declare w date := public.cur_week();
begin
  if not exists (select 1 from public.mission_week where week = w) then
    insert into public.mission_week (week, slot, kind, target, text, coins, xp, zcoin, chips)
    select w, row_number() over (order by grp, h), kind, target, text, coins, xp, zcoin, chips from (
      (select 1 grp, md5(id::text || w::text) h, * from public.mission_pool where zcoin > 0 order by 2 limit 1)
      union all (select 2, md5(id::text || w::text), * from public.mission_pool where chips > 0 order by 2 limit 1)
      union all (select 3, md5(id::text || w::text), * from public.mission_pool where zcoin = 0 and chips = 0 order by 2 limit 3)
    ) q on conflict do nothing;
  end if;
  return w;
end $function$;
CREATE FUNCTION public.xp_mult() RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $function$ select coalesce((select max(mult) from public.xp_events where now() >= starts_at and now() < ends_at), 1); $function$;
create function public.handle_new_user() returns trigger language plpgsql as $$ begin return new; end $$;
insert into public.seasons values (1,'S1',now()-interval '1 day',now()+interval '50 days',40,1000,600);
insert into public.mission_pool values (1,'kills',10,'mate 10',300,2000,15,0),(2,'matches',1,'jogue 1',500,2000,0,1),(3,'kills',5,'mate 5',700,3000,0,0),(4,'wins',1,'venca',1000,4000,0,0),(5,'wave_any',5,'onda 5',400,2000,0,0);
CREATE FUNCTION public.start_run(p_map text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
declare uid uuid := auth.uid(); rid bigint;
begin
  if uid is null then raise exception 'SEM_LOGIN'; end if;
  if p_map !~ '^[a-z0-9_]{2,20}$' then raise exception 'MAPA_INVALIDO'; end if;
  update public.runs set ended_at = now(), accepted = false, reason = 'abandonada' where user_id = uid and ended_at is null;
  insert into public.runs (user_id, map_id) values (uid, p_map) returning id into rid;
  update public.profiles set last_seen = now() where id = uid;
  return rid;
end $function$;
